#[cfg(feature = "bench-support")]
#[doc(hidden)]
#[must_use]
pub fn holder_read_cost(pid: i32, reads: usize, kept: bool) -> (f64, f64, f64, String) {
    holder_image::cut_cost::read_cost(pid, reads, kept)
}
